insert into ragams (id, name, description, time_of_day) values
  ('bhairavi', 'Bhairavi', 'A profound and expressive raga often called the queen of ragas. Its rich, emotive phrases have been used for centuries in devotional and contemplative music.', 'morning'),
  ('neelambari', 'Neelambari', 'The lullaby raga, used for centuries to induce sleep. Its gentle, descending phrases calm the nervous system.', 'night'),
  ('sahana', 'Sahana', 'An emotive raga of longing and surrender. Its contemplative phrases draw the listener inward, ideal for breathwork and presence.', 'evening'),
  ('hindolam', 'Hindolam', 'A pentatonic raga of deep serenity. Its simple, swinging phrases create a meditative space that requires no effort to enter.', 'morning'),
  ('mohanam', 'Mohanam', 'A bright, uplifting pentatonic raga. Its joyful, ascending phrases energize the mind and lift the spirit without overstimulating.', 'afternoon'),
  ('kalyani', 'Kalyani', 'An expansive, luminous raga associated with auspiciousness. Its wide-ranging phrases open the chest and create a feeling of spaciousness.', 'evening'),
  ('todi', 'Todi', 'A majestic morning raga of quiet intensity. Its slow, deliberate phrases demand full attention and reward it with profound stillness.', 'morning');
insert into tracks (id, title, ragam_id, scenarios, tags, description, artist_note, recorded_date, location, duration, audio_url, free, created_at) values
  ('bhairavi-focus-01', 'Morning Bhairavi — Deep Focus', 'bhairavi', '{focus}', '{grounding,concentration,warmth}', 'A grounding Bhairavi improvisation with percussion. Its rich phrases sharpen concentration and sustain deep focus.', 'The mridangam player and I had been practicing together for weeks. That morning everything locked in — the rhythm became invisible, just a pulse you could think inside of.', '2025-01-12', 'Home studio, Portland', 2700, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/Bhairavi_440Hz_with_percussion.m4a', true, '2025-01-12T00:00:00Z'),
  ('bhairavi-meditate-01', null, 'bhairavi', '{meditate,focus}', '{devotional,introspective,warmth}', 'Recorded before sunrise in Chennai. A slow, deeply internal Bhairavi that builds from silence into rich, emotive phrases.', 'I woke at 4am and the city was completely still. The shruti box was already warm from the night before. This one played itself.', '2024-11-20', 'Before sunrise, Chennai', 3600, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/deepwaters011526audioexport.m4a', true, '2024-11-20T00:00:00Z'),
  ('bhairavi-sleep-01', null, 'bhairavi', '{sleep}', '{gentle,surrender,rain}', 'A late-night Bhairavi after a long rain. Softer and slower than the morning sessions, letting the phrases dissolve into silence.', 'It had been raining all day and I didn''t want to play anything structured. I just followed the sound of the rain and let Bhairavi fill in the spaces between drops.', '2025-02-14', 'Late night after rain, Portland', 5400, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/deepwaters01232026audioexport.m4a', true, '2025-02-14T00:00:00Z'),
  ('bhairavi-focus-02', null, 'bhairavi', '{focus}', '{steady,concentration,percussion}', 'A rhythmically driven Bhairavi with strong percussion anchoring the improvisation. Good for sustained work sessions.', 'Sunday mornings are when I practice the most demanding material. This one started as a technical exercise and turned into something I actually wanted to listen back to.', '2025-03-08', 'Sunday morning, home studio', 2700, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/homepraactice06032026.m4a', false, '2025-03-08T00:00:00Z'),
  ('bhairavi-meditate-02', 'Bhairavi at Dawn', 'bhairavi', '{meditate}', '{devotional,stillness,dawn}', 'An early morning session near the Mylapore temple quarter. The temple bells are faintly audible in the background.', 'Kapaleeshwarar temple bells started ringing midway through. I didn''t stop — they became part of the raga.', '2024-09-15', 'Mylapore temple quarter, Chennai', 3600, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/Bhairavi_440Hz_with_percussion.m4a', true, '2024-09-15T00:00:00Z');
insert into tracks (id, title, ragam_id, scenarios, tags, description, artist_note, recorded_date, location, duration, audio_url, free, created_at) values
  ('neelambari-sleep-01', 'Neelambari Lullaby', 'neelambari', '{sleep}', '{calm,surrender,warmth}', 'The quintessential lullaby raga with gentle percussion. Its descending phrases calm the nervous system and ease you into rest.', 'My grandmother used to hum Neelambari to put us to sleep. I never learned it from her formally — it just lived in my ear all these years. This is my version of her lullaby.', '2024-12-03', 'At dusk by the Willamette', 3600, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/deepwaters011526audioexport.m4a', true, '2024-12-03T00:00:00Z'),
  ('neelambari-sleep-02', null, 'neelambari', '{sleep}', '{silence,gentle,minimal}', 'A sparse, unhurried Neelambari with long pauses between phrases. Each note is placed deliberately, then allowed to fade.', 'I was experimenting with how much silence a raga can hold before it stops being music. Neelambari held more than I expected.', '2025-01-28', 'Quiet evening, Portland', 5400, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/deepwaters01232026audioexport.m4a', true, '2025-01-28T00:00:00Z'),
  ('neelambari-meditate-01', null, 'neelambari', '{meditate,sleep}', '{contemplative,midnight,stillness}', 'An after-midnight Neelambari that blurs the line between meditation and sleep. The phrases are slow enough to follow with the breath.', 'This was originally meant for sleep but friends said it kept them present rather than drowsy. So it lives in both worlds.', '2025-02-01', 'After midnight, home studio', 3600, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/homepraactice06032026.m4a', true, '2025-02-01T00:00:00Z'),
  ('neelambari-sleep-03', 'Neelambari for Rest', 'neelambari', '{sleep}', '{lullaby,warmth,traditional}', 'A traditional rendering of Neelambari in the style it has been sung for centuries — as a lullaby. Recorded during a visit to Thanjavur.', 'Thanjavur is where so much of this music was codified. Playing Neelambari there felt less like performing and more like remembering something ancient.', '2024-10-22', 'Guest room session, Thanjavur', 3600, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/Bhairavi_440Hz_with_percussion.m4a', false, '2024-10-22T00:00:00Z');
insert into tracks (id, title, ragam_id, scenarios, tags, description, artist_note, recorded_date, location, duration, audio_url, free, created_at) values
  ('sahana-meditate-01', 'Sahana — Contemplation', 'sahana', '{meditate}', '{contemplative,longing,surrender}', 'A deeply emotive Sahana improvisation for meditation. Its contemplative phrases draw the listener inward, ideal for breathwork and presence.', 'Sahana always takes me somewhere I wasn''t planning to go. This morning it went to a place of real longing — not sadness, just the ache of paying close attention to something beautiful.', '2025-02-08', 'Morning session, Chennai', 3600, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/deepwaters011526audioexport.m4a', true, '2025-02-08T00:00:00Z'),
  ('sahana-focus-01', null, 'sahana', '{focus,meditate}', '{bittersweet,flowing,rain}', 'An overcast afternoon Sahana with a gentle ache. The phrases flow continuously, creating a backdrop that sustains attention without demanding it.', 'Portland in December is all grey sky and soft light. Sahana fits that mood perfectly — it doesn''t try to brighten anything, just sits with you in the overcast.', '2024-12-18', 'Overcast afternoon, Portland', 2700, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/deepwaters01232026audioexport.m4a', true, '2024-12-18T00:00:00Z'),
  ('sahana-sleep-01', null, 'sahana', '{sleep}', '{tender,surrender,new year}', 'A New Year''s evening Sahana — tender, unhurried, winding down. Recorded as the year turned over, carrying a sense of release.', 'Everyone else was out celebrating. I stayed home and played Sahana as the year ended. It felt like the right way to let go of everything that year held.', '2025-01-01', 'New Year''s evening, home studio', 5400, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/homepraactice06032026.m4a', true, '2025-01-01T00:00:00Z'),
  ('sahana-meditate-02', null, 'sahana', '{meditate}', '{ocean,expansive,surrender}', 'Sahana beside the ocean at Mahabalipuram. The waves provided a natural tanpura, and the phrases stretched longer than usual.', 'The shore temple was right there. Centuries of devotion soaked into the stone. I think the raga knew.', '2025-03-01', 'Beside the ocean, Mahabalipuram', 3600, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/Bhairavi_440Hz_with_percussion.m4a', false, '2025-03-01T00:00:00Z');
insert into tracks (id, title, ragam_id, scenarios, tags, description, artist_note, recorded_date, location, duration, audio_url, free, created_at) values
  ('hindolam-meditate-01', null, 'hindolam', '{meditate}', '{serene,pentatonic,effortless}', 'A courtyard Hindolam in Chennai. The pentatonic simplicity removes all tension — each phrase swings gently like a pendulum.', 'Five notes. That''s all Hindolam gives you. But in that courtyard with the jasmine and the evening breeze, five notes were more than enough.', '2024-10-15', 'Courtyard session, Chennai', 3600, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/deepwaters011526audioexport.m4a', true, '2024-10-15T00:00:00Z'),
  ('hindolam-focus-01', 'Hindolam — Morning Clarity', 'hindolam', '{focus}', '{clarity,bright,morning}', 'A crisp morning Hindolam with gentle percussion. The pentatonic structure keeps the mind clear without wandering.', 'I play Hindolam when I need to clear my own head before a long day. This one did exactly that — by the end I felt like the fog had lifted.', '2025-01-05', 'First light, Portland', 2700, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/deepwaters01232026audioexport.m4a', true, '2025-01-05T00:00:00Z'),
  ('hindolam-sleep-01', null, 'hindolam', '{sleep,meditate}', '{rain,gentle,dissolving}', 'A rainy evening Hindolam that dissolves gradually into near-silence. The rain on the studio roof became part of the texture.', 'I kept playing softer and softer until I couldn''t tell where the music ended and the rain began. That''s when I knew it was done.', '2025-02-10', 'Rainy evening, home studio', 5400, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/homepraactice06032026.m4a', true, '2025-02-10T00:00:00Z'),
  ('hindolam-meditate-02', null, 'hindolam', '{meditate}', '{gratitude,grounding,holiday}', 'A Thanksgiving morning session. The raga felt like gratitude — simple, warm, complete in itself.', 'The house smelled like sambar and coffee. My parents were visiting. I played this before anyone else woke up, just grateful for the morning.', '2024-11-28', 'Thanksgiving morning, Portland', 1800, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/Bhairavi_440Hz_with_percussion.m4a', true, '2024-11-28T00:00:00Z'),
  ('hindolam-focus-02', null, 'hindolam', '{focus}', '{fog,steady,quiet}', 'Recorded on a foggy Sellwood morning. A steady, unadorned Hindolam that sits quietly beside you while you work.', 'Sellwood disappears in the fog some mornings. You can''t see past the yard. That kind of containment is perfect for Hindolam — nowhere to go, nothing to prove.', '2025-03-15', 'Foggy dawn, Sellwood', 2700, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/deepwaters011526audioexport.m4a', false, '2025-03-15T00:00:00Z');
insert into tracks (id, title, ragam_id, scenarios, tags, description, artist_note, recorded_date, location, duration, audio_url, free, created_at) values
  ('mohanam-focus-01', null, 'mohanam', '{focus}', '{bright,energizing,joyful}', 'A sunny afternoon Mohanam full of ascending phrases. Bright and energizing without tipping into restlessness.', 'One of those rare November days in Portland where the sun comes out and everyone goes a little crazy with happiness. The raga caught that energy.', '2024-11-03', 'Sunny afternoon, Portland', 2700, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/deepwaters01232026audioexport.m4a', true, '2024-11-03T00:00:00Z'),
  ('mohanam-focus-02', 'Mohanam — Bright Focus', 'mohanam', '{focus,meditate}', '{uplifting,percussion,weekend}', 'A weekend session with strong percussion. The rhythm and melody together create a joyful momentum that carries deep work.', 'Weekend mornings with no agenda are when the best sessions happen. No pressure, no clock — just the raga and the tala finding each other.', '2025-01-22', 'Weekend session, home studio', 2700, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/homepraactice06032026.m4a', true, '2025-01-22T00:00:00Z'),
  ('mohanam-meditate-01', null, 'mohanam', '{meditate}', '{garden,birdsong,gentle}', 'A garden session in Chennai where birdsong wove through the phrases. A gentler Mohanam, more contemplative than bright.', 'The crows and mynahs kept joining in. At some point I stopped trying to play over them and started playing with them.', '2025-02-18', 'Garden session, Chennai', 3600, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/Bhairavi_440Hz_with_percussion.m4a', true, '2025-02-18T00:00:00Z'),
  ('mohanam-focus-03', null, 'mohanam', '{focus}', '{cozy,steady,afternoon}', 'A compact afternoon Mohanam recorded at a quiet corner table. Steady and contained — good for short focus sprints.', 'I brought a small recorder to my favorite coffee shop and played quietly in the corner. The barista asked what raga it was. That made my day.', '2024-12-10', 'Coffee shop corner, Sellwood', 1800, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/deepwaters011526audioexport.m4a', true, '2024-12-10T00:00:00Z');
insert into tracks (id, title, ragam_id, scenarios, tags, description, artist_note, recorded_date, location, duration, audio_url, free, created_at) values
  ('kalyani-focus-01', null, 'kalyani', '{focus}', '{expansive,bright,year-end}', 'A year-end Kalyani session with wide, ascending phrases. The expansiveness of the raga matches the reflective mood of December.', 'End of the year, looking back at everything. Kalyani felt right — it''s a raga that holds both joy and gravity at the same time.', '2024-12-28', 'Year-end session, Portland', 2700, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/homepraactice06032026.m4a', true, '2024-12-28T00:00:00Z'),
  ('kalyani-meditate-01', 'Kalyani at Twilight', 'kalyani', '{meditate}', '{twilight,devotional,spacious}', 'Recorded after visiting the Ranganathaswamy temple in Trichy. The evening light and the scale of the temple infused the session.', 'The gopuram was still glowing when I sat down to play. Some ragas carry the architecture of the spaces they''re played in.', '2025-02-05', 'Temple visit aftermath, Trichy', 3600, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/Bhairavi_440Hz_with_percussion.m4a', true, '2025-02-05T00:00:00Z'),
  ('kalyani-focus-02', null, 'kalyani', '{focus,meditate}', '{snow,quiet,mountain}', 'A snowy morning Kalyani from a cabin near Mt. Hood. The silence of snow and the brightness of the raga in perfect balance.', 'Snow absorbs sound. Playing Kalyani in that silence felt like the notes had nowhere to go but inward. The mountain was listening.', '2025-01-15', 'Snowy morning, Mt. Hood cabin', 2700, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/deepwaters011526audioexport.m4a', false, '2025-01-15T00:00:00Z'),
  ('kalyani-sleep-01', null, 'kalyani', '{sleep}', '{late night,unwinding,soft}', 'A rare late-night Kalyani, slower and softer than its usual bright character. The expansiveness here becomes a kind of gentle floating.', 'Kalyani is usually a daytime raga but I couldn''t sleep and it''s what came out. Played very slowly, it became something completely different — weightless.', '2025-03-05', 'Late night improvisation, home studio', 5400, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/deepwaters01232026audioexport.m4a', true, '2025-03-05T00:00:00Z');
insert into tracks (id, title, ragam_id, scenarios, tags, description, artist_note, recorded_date, location, duration, audio_url, free, created_at) values
  ('todi-meditate-01', 'Todi — First Light', 'todi', '{meditate}', '{intense,predawn,stillness}', 'A predawn Todi of quiet intensity. Each phrase is placed with deliberation, demanding and rewarding full attention.', 'Todi asks you to slow down completely. You can''t rush it. The raga won''t let you.', '2024-10-30', 'Predawn session, Chennai', 3600, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/homepraactice06032026.m4a', true, '2024-10-30T00:00:00Z'),
  ('todi-focus-01', null, 'todi', '{focus}', '{deliberate,deep,saturday}', 'A quiet Saturday Todi. The deliberate pace creates a container for deep, sustained work — not background music, but a companion.', 'Todi on a Saturday morning is my version of going to the gym. It''s demanding, it requires your full attention, and you feel completely different afterward.', '2025-01-18', 'Quiet Saturday, Portland', 2700, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/Bhairavi_440Hz_with_percussion.m4a', true, '2025-01-18T00:00:00Z'),
  ('todi-meditate-02', null, 'todi', '{meditate,focus}', '{temple bells,morning,sacred}', 'Todi after the morning temple bells in Mylapore. The raga carries the weight of centuries of morning practice in this neighborhood.', 'Mylapore mornings are sacred. Musicians have been playing Todi at this hour in this neighborhood for hundreds of years. I''m just the latest in a long line.', '2025-02-22', 'After temple bells, Mylapore', 3600, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/deepwaters01232026audioexport.m4a', false, '2025-02-22T00:00:00Z'),
  ('todi-sleep-01', null, 'todi', '{sleep}', '{midnight,sparse,dissolving}', 'A midnight Todi — unusual for a morning raga, but the sparse phrasing and long silences work beautifully for winding down.', 'My teacher would say you shouldn''t play Todi at midnight. But rules in music are just suggestions once you''ve internalized them. This one wanted to be played.', '2024-12-15', 'Midnight session, home studio', 5400, 'https://pub-1a2eea0965e14d279ebdbbe8bd7c34bf.r2.dev/tracks/deepwaters011526audioexport.m4a', true, '2024-12-15T00:00:00Z');
